'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );


// MAIN //

/**
* Returns the first index of an element in a double-precision complex floating-point strided array which is not equal to a specified search element using alternative indexing semantics.
*
* ## Notes
*
* -   If all elements are equal to the search element, the function returns `-1`.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex128} searchElement - search element
* @param {Complex128Array} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {integer} index
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 1.0, 2.0, 0.0, 0.0, 1.0, 2.0 ] );
*
* var idx = zindexOfNotEqual( x.length, new Complex128( 1.0, 2.0 ), x, 1, 0 );
* // returns 2
*/
function zindexOfNotEqual( N, searchElement, x, strideX, offsetX ) {
	var view;
	var re;
	var im;
	var ix;
	var i;

	if ( N <= 0 ) {
		return -1;
	}

	// Decompose the search element into its real and imaginary components:
	re = real( searchElement );
	im = imag( searchElement );

	// Reinterpret the complex input array as a real-valued array of interleaved real and imaginary components:
	view = reinterpret( x, 0 );

	// Adjust the stride and offset to account for the interleaved storage:
	ix = offsetX * 2;
	strideX *= 2;

	for ( i = 0; i < N; i++ ) {
		if ( view[ ix ] !== re || view[ ix+1 ] !== im ) {
			return i;
		}
		ix += strideX;
	}
	return -1;
}


// EXPORTS //

module.exports = zindexOfNotEqual;
